#if MASHBOX_STUDIO_TESTS
using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioBridgeProfileValidation
{
 const BindingFlags F=BindingFlags.Static|BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static int checks,stage;static StudioModelDocument doc;static StudioModelEditor ed;static SceneView view;static ToolChannelPane pane;static double next;static string failure;static Material material;
 static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}
 static object Old(string n,params object[] a)=>typeof(StudioBridgeValidation).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(null,a);
 static object Call(string n,params object[] a)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length&&m.GetParameters().Select((p,i)=>a[i]==null||p.ParameterType.IsInstanceOfType(a[i])).All(b=>b)).Invoke(ed,a);
 static object Get(string n)=>typeof(StudioModelEditor).GetField(n,F).GetValue(ed);
 static StudioModelDocument.Node Panels(int n=2)=> (StudioModelDocument.Node)Old("Panels",n,1,1f);
 static (int a,int b)[] Borders(StudioModelDocument.Node n)=>(ValueTuple<int,int>[])Old("PanelEdges",n,0,1f);
 static void Select(){ed.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);var pairs=Borders(doc.nodes[0]);var edges=(List<(int a,int b)>)Call("Edges");ed.Components.Clear();foreach(var e in pairs){int index=edges.FindIndex(v=>v==e||v==(e.b,e.a));Check(index>=0,"Source edge lookup");ed.Components.Add(index);}Call("EstablishSelectionBaseline");}
 static void Geometry()
 {
  Old("Geometry");
  foreach(int count in new[]{1,2,5})foreach(int divisions in new[]{0,1,2,4,8})foreach(float curvature in new[]{-1f,-.5f,0f,.5f,1f})
  {
   var n=Panels(count);var original=n.mesh.vertices;var originalNormals=n.mesh.normals;var originalColors=n.mesh.colors;var originalTriangles=Enumerable.Range(0,n.mesh.subMeshCount).Select(n.mesh.GetTriangles).ToArray();var top=new StudioMeshCuts(n);int faces=top.Faces.Count;
   int added=top.BridgeEdges(n,Borders(n),divisions,curvature);Check(added==count*(divisions+1),"Division face count");Check(n.mesh.vertexCount==original.Length+4*added,"Generated quad attributes");Check(n.mesh.vertices.Take(original.Length).SequenceEqual(original),"Source/boundary vertices moved");Check(n.mesh.normals.Take(original.Length).SequenceEqual(originalNormals),"Source normals changed");Check(n.mesh.colors.Take(original.Length).SequenceEqual(originalColors),"Source colors changed");for(int channel=0;channel<8;channel++)Check(n.mesh.GetVertexAttributeDimension((UnityEngine.Rendering.VertexAttribute)((int)UnityEngine.Rendering.VertexAttribute.TexCoord0+channel))==new[]{4,3,2}[channel%3],"UV channel dimension changed");
   for(int sub=0;sub<n.mesh.subMeshCount;sub++)Check(n.mesh.GetTriangles(sub).Take(originalTriangles[sub].Length).SequenceEqual(originalTriangles[sub]),"Source index prefix changed");
   Old("Verify",n,faces);Check(new StudioMeshCuts(n).Faces.Count==faces+added,"Authored divisions missing");
   var generated=n.mesh.vertices.Skip(original.Length).ToArray();if(divisions==0||curvature==0)Check(generated.All(p=>Mathf.Abs(p.z)<1e-6f),"Flat bridge bowed");else Check(curvature>0?generated.Max(p=>p.z)>.05f:generated.Min(p=>p.z)<-.05f,"Signed curvature direction");
   if(divisions>0){var plan=top.LastBridgeProfile;var expected=plan.Evaluate(curvature).ToArray();plan.Apply(n.mesh,0);plan.Apply(n.mesh,curvature);Check(n.mesh.vertices.SequenceEqual(expected),"Curvature replay accumulated or changed topology");Check(n.mesh.vertexCount==original.Length+4*added,"Replay changed vertex count");}
   Object.DestroyImmediate(n.mesh);
  }
  foreach(float scale in new[]{.001f,1f,100f})foreach(float curve in new[]{-1f,0f,1f}){var n=Panels(2);var v=n.mesh.vertices;for(int i=0;i<v.Length;i++){if(v[i].x<0)v[i].z=1;if(v[i].x>2)v[i].z=1;v[i]*=scale;}n.mesh.vertices=v;n.mesh.RecalculateNormals();n.mesh.RecalculateBounds();var top=new StudioMeshCuts(n);var edges=((List<(int a,int b)>)Old("Edges",top)).Where(e=>top.Positions[e.a].y!=top.Positions[e.b].y&&(top.Positions[e.a].x==0&&top.Positions[e.b].x==0||top.Positions[e.a].x==2*scale&&top.Positions[e.b].x==2*scale)).ToArray();Check(top.BridgeEdges(n,edges,4,curve)==10,"Sloped/scaled bridge count");Check(n.mesh.vertices.Take(v.Length).SequenceEqual(v),"Sloped/scaled source changed");var points=n.mesh.vertices.Skip(v.Length);if(curve!=0)Check(curve>0?points.Max(p=>p.z)>0:points.Min(p=>p.z)<0,"Sloped flow sign");Object.DestroyImmediate(n.mesh);}
  foreach(int count in new[]{4,8})foreach(int divisions in new[]{1,3})foreach(float curve in new[]{-1f,0,1f}){var n=(StudioModelDocument.Node)Old("Tubes",count);var top=new StudioMeshCuts(n);var edges=(List<(int a,int b)>)Old("Edges",top);var selected=edges.Where(e=>top.Positions[e.a].z==top.Positions[e.b].z&&(top.Positions[e.a].z==1||top.Positions[e.a].z==3)).ToArray();int old=top.Faces.Count;Check(top.BridgeEdges(n,selected,divisions,curve)==count*(divisions+1),"Closed loop profile count");Old("Verify",n,old);Object.DestroyImmediate(n.mesh);}
 }
 public static void Run(){EditorApplication.delayCall+=()=>{try{Geometry();doc=ScriptableObject.CreateInstance<StudioModelDocument>();doc.nodes.Add(Panels());ed=new StudioModelEditor(()=>view?.Repaint());ed.Load(doc);ed.SelectObject(0);Select();ToolChannelPane.SetFloatDefault("Bridge Edges","Divisions",4);ToolChannelPane.SetFloatDefault("Bridge Edges","Curvature",1);Call("OpenBridgeTool");Call("RemoveQueuedPreview");var kind=Enum.Parse(typeof(StudioModelEditor).GetNestedType("LiveTool",F),"Bridge");Call("EvaluateLiveTool",kind);pane=(ToolChannelPane)Get("bridgeToolPane");Check(pane,"Bridge options pane not open");Check(ed.ActiveMesh.vertices.Any(p=>p.z>.1f),"Live preview missing");var transaction=(StudioMeshToolPreview)Get("livePreview");var plan=transaction.Targets[0].Topology.LastBridgeProfile;var tris=ed.ActiveMesh.triangles;ToolChannelPane.SetFloatDefault("Bridge Edges","Curvature",-1);Call("EvaluateLiveTool",kind);Check(ReferenceEquals(plan,transaction.Targets[0].Topology.LastBridgeProfile),"Curvature rebuilt profile");Check(ed.ActiveMesh.triangles.SequenceEqual(tris),"Curvature rebuilt indices");Check(ed.ActiveMesh.vertices.Any(p=>p.z<-.1f),"Concave live preview missing");Call("CancelLiveTool",false);Check(ed.ActiveMesh.vertexCount==12,"Cancel did not restore source");Select();ToolChannelPane.SetFloatDefault("Bridge Edges","Curvature",1);Call("EvaluateLiveTool",kind);view=ScriptableObject.CreateInstance<SceneView>();typeof(SceneView).GetProperty("customScene",F).SetValue(view,ed.Scene);view.position=new Rect(100,100,1000,750);view.Show();view.LookAtDirect(new Vector3(1,1,0),Quaternion.Euler(25,150,0),4);material=new Material(Shader.Find("Hidden/Internal-Colored"));material.SetInt("_Cull",0);material.SetInt("_ZWrite",1);material.SetInt("_ZTest",4);material.SetColor("_Color",Color.gray);SceneView.duringSceneGui+=Draw;next=EditorApplication.timeSinceStartup+1;EditorApplication.update+=Tick;view.Repaint();}catch(Exception e){Finish(e.ToString());}};}
 static void Draw(SceneView s){if(s!=view||Event.current.type!=EventType.Repaint)return;try{ed.SceneGUI(view,null);if(stage!=0)return;var rt=new RenderTexture(1000,750,24);rt.Create();var old=RenderTexture.active;var target=view.camera.targetTexture;var rect=view.camera.pixelRect;GL.PushMatrix();try{view.camera.targetTexture=rt;view.camera.pixelRect=new Rect(0,0,1000,750);Handles.SetCamera(new Rect(0,0,1000,750),view.camera);RenderTexture.active=rt;GL.Clear(true,true,new Color(.2f,.2f,.2f));GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;material.SetPass(0);Graphics.DrawMeshNow(ed.Transforms[0].GetComponent<MeshFilter>().sharedMesh,ed.Transforms[0].localToWorldMatrix);Call("DrawVisibleObjectWireframes",view.camera);var t=new Texture2D(1000,750,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,1000,750),0,0);t.Apply();Check(t.GetPixels32().Select(p=>p.r).Distinct().Count()>10,"No rendered rounded bridge");File.WriteAllBytes(Out("bridge-profile.png"),t.EncodeToPNG());Object.DestroyImmediate(t);stage=1;}finally{GL.PopMatrix();view.camera.targetTexture=target;view.camera.pixelRect=rect;RenderTexture.active=old;Object.DestroyImmediate(rt);}}catch(Exception e){failure=e.ToString();}}
 static void Tick(){if(EditorApplication.timeSinceStartup<next)return;try{if(failure!=null)throw new Exception(failure);if(stage==0){view.Repaint();return;}if(stage==1){UnityEditor.Undo.FlushUndoRecordObjects();Check(pane.ExecuteCommand(false),"Apply failed");Check(pane&&Get("livePreview")==null,"Apply did not retain pane or commit preview");UnityEditor.Undo.FlushUndoRecordObjects();ed.PerformWorkspaceHistory(false);Check(ed.ActiveMesh.vertexCount==12,"Undo bridge failed");ed.PerformWorkspaceHistory(true);Check(ed.ActiveMesh.vertexCount>12,"Redo bridge failed");ed.PerformWorkspaceHistory(false);Select();ToolChannelPane.SetFloatDefault("Bridge Edges","Divisions",2);ToolChannelPane.SetFloatDefault("Bridge Edges","Curvature",-.5f);var bridge=Enum.Parse(typeof(StudioModelEditor).GetNestedType("LiveTool",F),"Bridge");Call("EvaluateLiveTool",bridge);Check(pane.ExecuteCommand(true),"Execute failed");Check(!pane,"Execute did not close Bridge options");ed.PerformWorkspaceHistory(false);Select();Call("RepeatLastAction");Check(new StudioMeshCuts(doc.nodes[0]).Faces.Count==10,"Repeat did not retain divisions");Check(ed.ActiveMesh.vertices.Any(p=>p.z<-.05f),"Repeat did not retain curvature");ed.Components.Clear();Call("OpenBridgeTool");pane=(ToolChannelPane)Get("bridgeToolPane");Check(pane&&ed.StatusText.Contains("Select"),"No-selection Bridge lost ready pane/guidance");stage=2;next=EditorApplication.timeSinceStartup+.3;return;}Finish("PASS "+checks+" bridge profile geometry/cache/live-pane/cancel/history/render checks; legacy geometry corpus also passed");}catch(Exception e){Finish(e.ToString());}}
 static string Out(string n)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+n));
 static void Finish(string r){SceneView.duringSceneGui-=Draw;EditorApplication.update-=Tick;File.WriteAllText(Out("bridge-profile-result.txt"),r);EditorApplication.delayCall+=()=>{if(pane)pane.Close();if(view)view.Close();ed?.Dispose();if(material)Object.DestroyImmediate(material);EditorApplication.Exit(r.StartsWith("PASS")?0:1);};}
}
#endif

